//! Canonical HTMLUnknownElement for the general HTML unknown names.
//! https://html.spec.whatwg.org/multipage/dom.html#elements-in-the-dom
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><mystery id=unknown class=initial></mystery><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://unknown-fallback.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn unknown_fallback_descriptors_and_constructor_refusal(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLUnknownElement,P=C.prototype,g=Object.getOwnPropertyDescriptor(window,'HTMLUnknownElement'),a=Object.getOwnPropertyDescriptor(C,'prototype'),tag=Object.getOwnPropertyDescriptor(P,Symbol.toStringTag),x=document.getElementById('unknown');if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||Object.getPrototypeOf(P)!==HTMLElement.prototype||Object.getPrototypeOf(C)!==HTMLElement||P.constructor!==C||C.name!=='HTMLUnknownElement'||C.length!==0||g.enumerable||!g.writable||!g.configurable||g.value!==C||a.writable||a.enumerable||a.configurable||a.value!==P||tag.value!=='HTMLUnknownElement'||tag.writable||tag.enumerable||!tag.configurable)throw 'canonical unknown interface';var Bound=C.bind(null);for(var kind of [0,1,2]){var caught=false;try{if(kind===0)C();else if(kind===1)new C();else new Bound();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'no unknown constructor';}");}
#[test]
fn unknown_fallback_general_names_native_inert_and_actual_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLUnknownElement,P=C.prototype,doc=new Document();for(var tag of ['mystery','otherwise','widget','unknown','a1','a.b','svg','math','image']){var x=document.createElement(tag.toUpperCase()),y=doc.createElementNS('http://www.w3.org/1999/xhtml','t:'+tag);if(!(x instanceof C)||!(y instanceof C)||!(x instanceof HTMLElement)||!(x instanceof Element)||!(x instanceof Node)||Object.getPrototypeOf(x)!==P||Object.getPrototypeOf(y)!==P||x.localName!==tag||y.localName!==tag||x.ownerDocument!==document||y.ownerDocument!==doc||x.nodeType!==1||y.prefix!=='t'||Object.prototype.toString.call(x)!=='[object HTMLUnknownElement]')throw 'fixed actual unknown names';x.id='native';y.id='inert';if(x.getAttribute('id')!=='native'||y.getAttribute('id')!=='inert'||x.localName!==tag||y.localName!==tag)throw 'actual unknown data';}");}
#[test]
fn unknown_fallback_foreign_known_and_custom_names_keep_actual_interfaces(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLUnknownElement,doc=new Document();for(var tag of ['mystery','otherwise','widget','unknown','a1','a.b','svg','math','image']){if(document.createElementNS('urn:foreign',tag) instanceof C||doc.createElementNS('urn:foreign',tag) instanceof C)throw 'foreign element remains foreign';}for(var x of [document.createElement('div'),doc.createElementNS('http://www.w3.org/1999/xhtml','pre'),document.createElement('x-unknown'),doc.createElementNS('http://www.w3.org/1999/xhtml','x-unknown')]){if(x instanceof C||!(x instanceof HTMLElement))throw 'known and custom native interfaces '+x.localName+' '+Object.prototype.toString.call(x)+' '+(x instanceof C)+' '+(x instanceof HTMLElement);}");}
#[test]
fn unknown_fallback_saved_constructor_survives_global_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLUnknownElement,P=C.prototype;delete window.HTMLUnknownElement;for(var tag of ['mystery','otherwise','widget','unknown','a1','a.b','svg','math','image']){var x=document.createElement(tag),y=new Document().createElementNS('http://www.w3.org/1999/xhtml',tag);if(!(x instanceof C)||!(y instanceof C)||Object.getPrototypeOf(x)!==P||Object.getPrototypeOf(y)!==P)throw 'saved unknown canonical identity';}window.HTMLUnknownElement=function Fake(){};var z=document.createElement('blink');if(!(z instanceof C)||z instanceof window.HTMLUnknownElement||Object.getPrototypeOf(z)!==P)throw 'global override grants no native authority';");}
#[test]
fn unknown_fallback_inherited_attribute_handles_and_exact_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('unknown'),new Document().createElementNS('http://www.w3.org/1999/xhtml','t:blink')]){x.id='before';var attr=x.getAttributeNode('id'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.id='A\ud800Z';var records=watch.takeRecords();if(x.id!=='A\ud800Z'||x.getAttributeNode('id')!==attr||attr.value!==x.id||records.length!==1||records[0].attributeName!=='id'||records[0].oldValue!=='before'||!(x instanceof HTMLUnknownElement))throw 'actual unknown inherited data';x.removeAttribute('id');if(x.id!==''||attr.ownerElement!==null||attr.value!=='A\ud800Z')throw 'unknown inherited removal';}"#);}
#[test]
fn unknown_fallback_author_forgery_and_other_interface_brands_fail_before_hooks(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLUnknownElement,x=document.getElementById('unknown'),a=Object.getOwnPropertyDescriptor(Element.prototype,'id'),color=Object.getOwnPropertyDescriptor(HTMLFontElement.prototype,'color'),calls=0;for(var bad of [{},Object.create(C.prototype)]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'unknown prototype grants no native id';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'unknown forged brand before hooks';}var caught=false;try{color.set.call(x,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls||x.id!=='unknown')throw 'unknown has no font authority';");}
#[test]
fn unknown_fallback_child_class_and_origin_boundary_recover(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('unknown'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLUnknownElement,a=Object.getOwnPropertyDescriptor(frame.contentWindow.Element.prototype,'id'),calls=0;if(C===HTMLUnknownElement||Object.getPrototypeOf(C.prototype)!==frame.contentWindow.HTMLElement.prototype||a.get.call(x)!=='unknown')throw 'real child unknown interface';");p.set_location(&crate::navigation::address("https://other-unknown-fallback.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://unknown-fallback.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'unknown origin before hooks';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered'||!(x instanceof HTMLUnknownElement))throw 'unknown origin recovery';");}
#[test]
fn unknown_fallback_does_not_admit_unsupported_native_resource_copies(){for tag in ["mystery","otherwise"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.createElement('{tag}');x.id='kept';"));let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute("x.cloneNode(false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(!(x instanceof HTMLUnknownElement)||x.id!=='kept'||x.parentNode!==null)throw 'unknown copy refusal preserves source';x.id='recovered';if(x.id!=='recovered')throw 'unknown copy fresh recovery';");}}

#[test]
fn unknown_fallback_keeps_known_partial_interfaces_and_exact_names(){
 for tag in ["area","audio","base","caption","col","colgroup","datalist","del","details","dialog","embed","ins","map","object","optgroup","option","picture","selectedcontent","source","style","table","tbody","td","tfoot","th","thead","tr","track","video","frame","frameset","marquee","param"]{assert_ne!(crate::javascript::ordinary_html_interface(tag),Some("HTMLUnknownElement"),"known specialized HTML name {tag}");}
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document();for(var tag of ['DIV','FONT','SECTION','annotation-xml','color-profile','font-face','font-face-src','font-face-uri','font-face-format','font-face-name','missing-glyph']){var x=doc.createElementNS('http://www.w3.org/1999/xhtml',tag);if(!(x instanceof HTMLUnknownElement)||Object.getPrototypeOf(x)!==HTMLUnknownElement.prototype||x.localName!==tag||x.ownerDocument!==doc)throw 'exact HTML unknown-name fallback '+tag;}for(var tag of ['x-known','a-b','custom-element']){var x=document.createElement(tag),y=doc.createElementNS('http://www.w3.org/1999/xhtml','t:'+tag);if(Object.getPrototypeOf(x)!==HTMLElement.prototype||Object.getPrototypeOf(y)!==HTMLElement.prototype||x instanceof HTMLUnknownElement||y instanceof HTMLUnknownElement)throw 'valid custom name keeps HTMLElement';}");
}
